from collections import Counter

RANK = {r: i for i, r in enumerate("23456789", start=2)}
RANK.update({"10": 10, "J": 11, "Q": 12, "K": 13, "A": 14})


def parse_card(card):
    rank = card[:-1]
    return RANK[rank], card[-1]


def hand_rank(hand):
    cards = [parse_card(c) for c in hand.split()]
    ranks = sorted((r for r, _ in cards), reverse=True)
    suits = [s for _, s in cards]
    counts = Counter(ranks)
    # groups sorted by (count, rank) descending: e.g. full house -> triplet, pair
    groups = sorted(counts.items(), key=lambda kv: (kv[1], kv[0]), reverse=True)
    group_ranks = [r for r, c in groups]
    shape = sorted((c for _, c in groups), reverse=True)

    flush = len(set(suits)) == 1
    unique = sorted(set(ranks), reverse=True)
    # wheel: A 2 3 4 5
    wheel = ranks == [14, 5, 4, 3, 2]
    straight = len(unique) == 5 and (
        wheel or unique[0] - unique[4] == 4
    )
    straight_high = 5 if wheel else unique[0]

    if straight and flush:
        return (8, [straight_high])
    if shape == [4, 1]:
        return (7, group_ranks)
    if shape == [3, 2]:
        return (6, group_ranks)
    if flush:
        return (5, ranks)
    if straight:
        return (4, [straight_high])
    if shape == [3, 1, 1]:
        return (3, group_ranks)
    if shape == [2, 2, 1]:
        return (2, group_ranks)
    if shape == [2, 1, 1, 1]:
        return (1, group_ranks)
    return (0, ranks)


def best_hands(hands):
    scored = [(hand_rank(h), h) for h in hands]
    best = max(s for s, _ in scored)
    return [h for s, h in scored if s == best]

def can_chain(dominoes):
    if not dominoes:
        return []

    # Fix the first domino (as given); any valid chain can be rotated and
    # reversed so that it starts here.
    first = dominoes[0]
    remaining = dominoes[1:]

    def search(chain, right, pool):
        if not pool:
            return chain if chain[0][0] == right else None
        for i, (a, b) in enumerate(pool):
            if a == right:
                piece = (a, b)
            elif b == right:
                piece = (b, a)
            else:
                continue
            result = search(
                chain + [piece],
                piece[1],
                pool[:i] + pool[i + 1:],
            )
            if result is not None:
                return result
        return None

    return search([first], first[1], remaining)

class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 1
        self.first_roll = None  # first roll of the current frame
        # bonus phase (after the 10th frame)
        self.bonus_needed = 0
        self.bonus_done = 0
        self.bonus_first = None
        self.complete = False

    def roll(self, pins):
        if not 0 <= pins <= 10:
            raise Exception("pins must be between 0 and 10")
        if self.complete:
            raise Exception("game is already complete")

        self.rolls.append(pins)

        if self.bonus_needed > 0:
            if self.bonus_needed == 2:
                # bonus after a strike in the 10th frame
                if self.bonus_done == 0:
                    self.bonus_first = pins
                else:
                    if self.bonus_first != 10 and self.bonus_first + pins > 10:
                        raise Exception(
                            "two bonus rolls cannot knock down more than 10 pins"
                        )
            self.bonus_done += 1
            if self.bonus_done == self.bonus_needed:
                self.complete = True
            return

        if pins == 10:
            # strike
            if self.frame == 10:
                self.bonus_needed = 2
            else:
                self.frame += 1
        elif self.first_roll is None:
            self.first_roll = pins
        else:
            if self.first_roll + pins > 10:
                raise Exception(
                    "two rolls in a frame cannot knock down more than 10 pins"
                )
            if self.frame == 10:
                if self.first_roll + pins == 10:
                    # spare
                    self.bonus_needed = 1
                else:
                    self.complete = True
            else:
                self.frame += 1
            self.first_roll = None

    def score(self):
        if not self.complete:
            raise Exception("game is not complete")

        total = 0
        i = 0
        for _ in range(10):
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:
                total += 10 + self.rolls[i + 2]
                i += 2
            else:
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        return total

class Zipper:
    def __init__(self, node, crumbs):
        # crumbs: list of (parent node, "left" or "right") from root down
        self.node = node
        self.crumbs = crumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        return self.node["value"]

    def set_value(self, value):
        self.node["value"] = value
        return self

    def left(self):
        if self.node["left"] is None:
            return None
        return Zipper(self.node["left"], self.crumbs + [(self.node, "left")])

    def set_left(self, tree):
        self.node["left"] = tree
        return self

    def right(self):
        if self.node["right"] is None:
            return None
        return Zipper(self.node["right"], self.crumbs + [(self.node, "right")])

    def set_right(self, tree):
        self.node["right"] = tree
        return self

    def up(self):
        if not self.crumbs:
            return None
        parent, _ = self.crumbs[-1]
        return Zipper(parent, self.crumbs[:-1])

    def to_tree(self):
        zipper = self
        while zipper.crumbs:
            zipper = zipper.up()
        return zipper.node

